    assert.deepEqual(await list(), [first, second]);
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.equal((await fetch(`${base}/api/projects/999999`, {
      method: 'PATCH', body: JSON.stringify({ name: 'Missing' }),
